<?php
function backup_root(){global $CFG;$dir=$CFG['backup_dir']??(dirname(__DIR__,2).'/rs8_private_backups/'.substr(hash('sha256',__DIR__),0,16));if(!is_dir($dir)&&!mkdir($dir,0700,true))throw new Exception('Private backup directory is unavailable.');$dir=realpath($dir);$web=realpath(!empty($_SERVER['DOCUMENT_ROOT'])?$_SERVER['DOCUMENT_ROOT']:dirname(__DIR__));if($web&&str_starts_with(strtolower(str_replace('\\','/',$dir)).'/',strtolower(str_replace('\\','/',$web)).'/'))throw new Exception('Backup directory must be outside the public website folder.');return $dir;}
function backup_identifier($s){if(!preg_match('/^[A-Za-z0-9_]+$/D',$s))throw new Exception('Unsupported database identifier.');return '`'.$s.'`';}
function backup_rows_hash($rows){$lines=array_map(fn($r)=>json_encode($r,JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE),$rows);sort($lines,SORT_STRING);return hash('sha256',implode("\n",$lines));}
function backup_create($automatic=false){
 if(current_user()['role']!=='Admin')throw new Exception('Admin access required.');if(function_exists('set_time_limit'))set_time_limit(0);$ref='BACKUP-'.date('Ymd-His').'-'.bin2hex(random_bytes(4));db()->prepare("INSERT INTO process_backups(backup_ref,status,user_id) VALUES(?,'Creating',?)")->execute([$ref,current_user()['id']?:null]);$id=(int)db()->lastInsertId();$path=null;
 try{$path=backup_root().'/'.$ref.'.zip';$snapshot=['format'=>1,'at'=>date(DATE_ATOM),'tables'=>[]];$sql="SET NAMES utf8mb4;\nSET FOREIGN_KEY_CHECKS=0;\n";db()->beginTransaction();foreach(db()->query("SHOW FULL TABLES WHERE Table_type='BASE TABLE'")->fetchAll(PDO::FETCH_NUM) as $t){$table=$t[0];$ident=backup_identifier($table);$create=db()->query('SHOW CREATE TABLE '.$ident)->fetch(PDO::FETCH_NUM)[1];$rows=db()->query('SELECT * FROM '.$ident)->fetchAll();$snapshot['tables'][$table]=['create'=>$create,'rows'=>$rows,'hash'=>backup_rows_hash($rows)];$sql.=$create.";\n";foreach($rows as $r){$columns=implode(',',array_map('backup_identifier',array_keys($r)));$values=implode(',',array_map(fn($v)=>$v===null?'NULL':db()->quote((string)$v),array_values($r)));$sql.='INSERT INTO '.$ident.' ('.$columns.') VALUES('.$values.");\n";}}db()->commit();$sql.="SET FOREIGN_KEY_CHECKS=1;\n";
 $zip=new ZipArchive();if($zip->open($path,ZipArchive::CREATE|ZipArchive::EXCL)!==true)throw new Exception('Could not create backup archive.');$manifest=['reference'=>$ref,'created'=>date(DATE_ATOM),'automatic'=>$automatic,'files'=>[]];$json=json_encode($snapshot,JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE|JSON_THROW_ON_ERROR);$zip->addFromString('database.json',$json);$zip->addFromString('database.sql',$sql);$manifest['files']['database.json']=hash('sha256',$json);$manifest['files']['database.sql']=hash('sha256',$sql);
 $base=realpath(__DIR__);$walk=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($base,FilesystemIterator::SKIP_DOTS));foreach($walk as $file){if(!$file->isFile()||$file->isLink())continue;$real=$file->getRealPath();if(!str_starts_with(str_replace('\\','/',$real),str_replace('\\','/',$base).'/'))throw new Exception('Unexpected application file path.');$rel='application/'.str_replace('\\','/',substr($real,strlen($base)+1));$zip->addFile($real,$rel);$manifest['files'][$rel]=hash_file('sha256',$real);}$zip->addFromString('backup_manifest.json',json_encode($manifest,JSON_PRETTY_PRINT));if(!$zip->close())throw new Exception('Backup archive could not be finalized.');
 db()->prepare("UPDATE process_backups SET status='Complete',manifest_path=?,error_text=NULL WHERE id=?")->execute([$path,$id]);set_setting('backup_last_success',date(DATE_ATOM));audit('Backup complete','Backup',$ref,($automatic?'Scheduled':'Manual').' database + application + attachments backup; private storage.');return $id;
 }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();db()->prepare("UPDATE process_backups SET status='Failed',error_text=? WHERE id=?")->execute([safe_error_message($e),$id]);throw $e;}
}
function backup_record($id){$q=db()->prepare("SELECT * FROM process_backups WHERE id=? AND status='Complete'");$q->execute([$id]);$b=$q->fetch();if(!$b)throw new Exception('Completed backup not found.');$path=realpath($b['manifest_path']);$root=realpath(backup_root());if(!$path||!str_starts_with(str_replace('\\','/',$path),str_replace('\\','/',$root).'/')||basename($path)!==$b['backup_ref'].'.zip')throw new Exception('Backup file is unavailable.');$b['path']=$path;return $b;}
function backup_verify_restore($id){
 if(current_user()['role']!=='Admin')throw new Exception('Admin access required.');global $CFG;$b=backup_record($id);$zip=new ZipArchive();if($zip->open($b['path'])!==true)throw new Exception('Backup archive unreadable.');$temp='rs8_restore_'.bin2hex(random_bytes(8));$server=null;$created=false;
 try{$manifest=json_decode($zip->getFromName('backup_manifest.json'),true,512,JSON_THROW_ON_ERROR);foreach($manifest['files'] as $name=>$hash){$bytes=$zip->getFromName($name);if($bytes===false||!hash_equals($hash,hash('sha256',$bytes)))throw new Exception('Backup integrity failed: '.$name);}$snapshot=json_decode($zip->getFromName('database.json'),true,512,JSON_THROW_ON_ERROR);$server=db(false);if($temp===$CFG['db_name']||!preg_match('/^rs8_restore_[a-f0-9]{16}$/D',$temp))throw new Exception('Unsafe restore test target.');$server->exec('CREATE DATABASE '.backup_identifier($temp).' CHARACTER SET utf8mb4');$created=true;$server->exec('USE '.backup_identifier($temp));$server->exec('SET FOREIGN_KEY_CHECKS=0');foreach($snapshot['tables'] as $table=>$data){$ident=backup_identifier($table);if(!str_starts_with($data['create'],'CREATE TABLE '.$ident))throw new Exception('Unexpected backup schema.');$server->exec($data['create']);foreach($data['rows'] as $row){$cols=implode(',',array_map('backup_identifier',array_keys($row)));$q=$server->prepare('INSERT INTO '.$ident.' ('.$cols.') VALUES('.implode(',',array_fill(0,count($row),'?')).')');$q->execute(array_values($row));}$restored=$server->query('SELECT * FROM '.$ident)->fetchAll();if(!hash_equals($data['hash'],backup_rows_hash($restored)))throw new Exception('Restored data mismatch: '.$table);}$server->exec('SET FOREIGN_KEY_CHECKS=1');db()->prepare("UPDATE process_backups SET restore_test_at=NOW(),restore_test_status='Passed' WHERE id=?")->execute([$id]);audit('Backup restore test','Backup',$b['backup_ref'],count($snapshot['tables']).' tables and all attachment/file hashes verified in an isolated disposable database. Live database unchanged.');return count($snapshot['tables']);
 }catch(Throwable $e){db()->prepare("UPDATE process_backups SET restore_test_at=NOW(),restore_test_status='Failed',error_text=? WHERE id=?")->execute([safe_error_message($e),$id]);throw $e;}finally{$zip->close();if($created&&$server&&$temp!==$CFG['db_name']&&preg_match('/^rs8_restore_[a-f0-9]{16}$/D',$temp))$server->exec('DROP DATABASE '.backup_identifier($temp));}
}
function backup_automatic_run(){if(setting('backup_auto_enabled','1')!=='1')return null;$last=setting('backup_last_success','');if($last&&substr($last,0,10)===date('Y-m-d'))return null;return backup_create(true);}
